	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Tile size for the column dimension of B.
   *
   * We operate on B in blocks of columns to improve cache locality and
   * give the compiler a regular, vectorizable inner loop. This value is
   * heuristic; it is small enough to fit several rows of a tile in L1
   * while being large enough to amortize loop overhead.
   */
  const int TILE_J = 64;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM, unit lower triangular
// B is MxN, updated in place
//
// Original kernel (for reference):
//   for (i = 0; i < _PB_M; i++)
//     for (j = 0; j < _PB_N; j++) {
//       for (k = i+1; k < _PB_M; k++)
//         B[i][j] += A[k][i] * B[k][j];
//       B[i][j] = alpha * B[i][j];
//     }
//
// For each (i,j) it computes:
//   B_out[i,j] = alpha * ( B_in[i,j] + sum_{k=i+1}^{M-1} A[k,i] * B_in[k,j] )
//
// The optimized version below is mathematically *and numerically*
// equivalent for each element B[i][j]: the updates for a fixed (i,j)
// are performed in the same order over k, and the final scaling by
// alpha happens after all its updates, just as in the original code.
#pragma scop

  /* --------------------------------------------------------------------
   * Stage 1: accumulate strictly-lower-triangular contribution
   *
   * We rewrite the computation as:
   *   1) B_tmp[i,j] = B_in[i,j]
   *                     + sum_{k=i+1}^{M-1} A[k,i] * B_in[k,j];
   *   2) B_out[i,j] = alpha * B_tmp[i,j]
   *
   * Stage 1 below implements step (1) directly, *without* scaling.
   *
   * To improve data locality and vectorization opportunities, we:
   *   - iterate with k as the outer reduction index,
   *   - for each k, iterate over all i < k,
   *   - make j the innermost loop so B's row-major layout is accessed
   *     with unit stride in both B[i][j] and B[k][j],
   *   - block j in tiles of TILE_J columns to keep working sets in cache,
   *   - use temporary pointers and a scalar a_ki to keep hot data in
   *     registers and enable SIMD.
   *
   * For a fixed (i,j), the sequence of operations on B[i][j] is still:
   *   for k = i+1..M-1:  B[i][j] += A[k,i] * B[k][j];
   * in increasing k, exactly as in the original kernel.
   * ------------------------------------------------------------------ */
  for (int jb = 0; jb < _PB_N; jb += TILE_J)
  {
    int jend = jb + TILE_J;
    if (jend > _PB_N)
      jend = _PB_N;
    const int len = jend - jb;

    for (k = 1; k < _PB_M; ++k)
    {
      /* Row pointer into A and source row of B for this k.  */
      DATA_TYPE *restrict Ak = A[k];
      DATA_TYPE *restrict Bk = &B[k][jb];

      /* For each i < k, accumulate contribution from row k into row i. */
      for (i = 0; i < k; ++i)
      {
        const DATA_TYPE a_ki = Ak[i];         /* A[k][i], reused across j */
        DATA_TYPE *restrict Bi = &B[i][jb];   /* destination row segment */

        int jj = 0;

        /* Manually unrolled inner loop over columns j for better ILP and
         * to help the compiler generate efficient SIMD code.  Both Bi and
         * Bk are contiguous in memory along jj.
         */
        for (; jj + 3 < len; jj += 4)
        {
          Bi[jj    ] += a_ki * Bk[jj    ];
          Bi[jj + 1] += a_ki * Bk[jj + 1];
          Bi[jj + 2] += a_ki * Bk[jj + 2];
          Bi[jj + 3] += a_ki * Bk[jj + 3];
        }
        /* Handle the remaining columns in this tile. */
        for (; jj < len; ++jj)
        {
          Bi[jj] += a_ki * Bk[jj];
        }
      }
    }
  }

  /* --------------------------------------------------------------------
   * Stage 2: scale B by alpha
   *
   * After Stage 1, B holds:
   *   B[i,j] = B_in[i,j] + sum_{k=i+1}^{M-1} A[k,i] * B_in[k,j].
   *
   * We now perform:
   *   B[i,j] *= alpha;
   *
   * This matches the original kernel exactly: for each (i,j), all
   * additions over k were completed before multiplying by alpha.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_M; ++i)
  {
    DATA_TYPE *restrict Bi = B[i];

    j = 0;
    /* Unrolled scaling loop over columns to reduce loop overhead and
     * encourage vectorization.
     */
    for (; j + 3 < _PB_N; j += 4)
    {
      Bi[j    ] *= alpha;
      Bi[j + 1] *= alpha;
      Bi[j + 2] *= alpha;
      Bi[j + 3] *= alpha;
    }
    for (; j < _PB_N; ++j)
    {
      Bi[j] *= alpha;
    }
  }

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
