  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Optimized kernel.
   *
   * Original reference kernel:
   *
   *   for (i = 0; i < _PB_M; i++)
   *     for (j = 0; j < _PB_N; j++) {
   *       for (k = i+1; k < _PB_M; k++)
   *         B[i][j] += A[k][i] * B[k][j];
   *       B[i][j] = alpha * B[i][j];
   *     }
   *
   * This computes (with A unit lower-triangular):
   *   B_out[i,j] = alpha * ( B_in[i,j]
   *                          + sum_{k=i+1..M-1} A[k,i] * B_in[k,j] )
   * which is BLAS TRMM with:
   *   SIDE='L', UPLO='L', TRANSA='T', DIAG='U'
   * so B := alpha * A^T * B.
   *
   * The implementation below uses an equivalent two-phase algorithm:
   *
   *   1) ACCUMULATE strictly-lower-triangular contributions:
   *        B[i,j] += A[k,i] * B[k,j]   for all 0 <= i < k < M, 0 <= j < N
   *
   *      After this phase:
   *        B[i,j] = B_in[i,j] + sum_{k=i+1..M-1} A[k,i] * B_in[k,j]
   *
   *   2) SCALE by alpha:
   *        B[i,j] *= alpha
   *
   *      After scaling:
   *        B[i,j] = alpha * ( B_in[i,j]
   *                           + sum_{k=i+1..M-1} A[k,i] * B_in[k,j] )
   *
   * This is algebraically identical to the original kernel, but the loop
   * order in phase (1) is changed to (k, i, j). For each fixed (k,i) we
   * traverse the contiguous j-dimension of B[i,*] and B[k,*], which:
   *   - greatly improves spatial locality,
   *   - exposes a simple, vectorizable inner loop over j,
   *   - keeps all computations in-place without extra buffers.
   */

#pragma scop
  {
    const int Mdim = _PB_M;
    const int Ndim = _PB_N;

    /* Tunable column blocking factor for B.  This limits the working-set
       size of the two rows B[i][*] and B[k][*] that are active together,
       improving L1/L2 cache utilization. */
    const int Tj = 64;

    /* Phase 1: accumulate strictly-lower-triangular contributions.
       Loop order: k -> i -> (jj, j) with j as the innermost index.

       For each source row k, all target rows i < k receive:
         B[i, :] += A[k, i] * B[k, :]

       For a fixed (k,i), A[k][i] is loaded once and reused across the
       entire j-range (blocked in chunks of size Tj). B[k][*] and B[i][*]
       are both accessed with unit stride in j.
    */
    for (k = 1; k < Mdim; ++k) {
      /* Rows i that are strictly above k. */
      for (i = 0; i < k; ++i) {
        DATA_TYPE a_ki = A[k][i];

        /* Process columns in blocks for better cache locality and to
           provide the compiler with a clear, vectorizable inner loop. */
        for (int jj = 0; jj < Ndim; jj += Tj) {
          int j_end = jj + Tj;
          if (j_end > Ndim)
            j_end = Ndim;

          /* Row pointers for the current block of columns. These are
             marked 'restrict' to tell the compiler that Bi and Bk refer
             to disjoint memory regions (i < k => different rows), which
             helps automatic vectorization. */
          DATA_TYPE *restrict Bi = &B[i][jj];
          DATA_TYPE *restrict Bk = &B[k][jj];

          /* Innermost loop: contiguous in memory for both Bi and Bk. */
          for (j = 0; j < j_end - jj; ++j) {
            Bi[j] += a_ki * Bk[j];
          }
        }
      }
    }

    /* Phase 2: scale B by alpha.
       This is a simple, embarrassingly parallel 2D map, and it is
       separated from phase (1) so that all reads of B[k][j] as inputs
       during the accumulation see the original (unscaled) values. */
    for (i = 0; i < Mdim; ++i)
      for (j = 0; j < Ndim; ++j)
        B[i][j] *= alpha;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

