     B[i,j] = alpha * ( B_in[i,j] + sum_{k=i+1..M-1} A[k,i] * B_in[k,j] )

   where B_in is the value of B at kernel entry.

   The optimized kernel below:

     1. Reorders the computation as:

          for (k = 1..M-1)
            for (i = 0..k-1)
              for (j = 0..N-1)
                B[i][j] += A[k][i] * B[k][j];

        followed by a separate scaling phase:

          for (i,j)
            B[i][j] *= alpha;

        This is algebraically equivalent to the original code and still uses
        only the original (un-updated) B[k][j] values as sources.

     2. Applies cache blocking in (k, i, j) to improve locality.

     3. Uses pointers to contiguous tiles of B to give the compiler a simple,
        unit-stride innermost loop that vectorizes well.

     4. Optionally parallelizes over blocks of columns (j-tiles) when
        compiled with OpenMP; without -fopenmp the pragmas are ignored. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;
  int I, J, K;

  /* Tunable tile sizes.
     TM controls blocking in the M dimension (rows of A/B) for both i and k.
     TN controls blocking in the N dimension (columns of B). */
  const int TM = 32;
  const int TN = 128;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM (unit lower triangular)
// B is MxN
#pragma scop

  /* --------------------------------------------------------------------
   * Step 1: accumulate strictly-lower-triangular contribution
   *
   * We implement:
   *   for k = 1..M-1
   *     for i = 0..k-1
   *       for j = 0..N-1
   *         B[i][j] += A[k][i] * B[k][j];
   *
   * in a cache-blocked form. This is equivalent to the original kernel's
   * triple loop but provides better data reuse and a unit-stride inner
   * loop over j (columns of B). For each fixed (k, i) pair, A[k][i] is
   * loaded once and reused across a contiguous tile of columns of B. */
#ifdef _OPENMP
  /* Parallelize over independent column tiles when OpenMP is enabled. */
#pragma omp parallel for schedule(static)
#endif
  for (J = 0; J < _PB_N; J += TN)
  {
    int Jend = (J + TN < _PB_N) ? (J + TN) : _PB_N;

    for (K = 1; K < _PB_M; K += TM)
    {
      int Kend = (K + TM < _PB_M) ? (K + TM) : _PB_M;

      /* For a given k in [K, Kend), only rows i in [0, k) contribute.
         Since k < Kend, all such i satisfy i < Kend, so we can restrict
         i to [0, Kend). We then tile this [0, Kend) interval by I. */
      for (I = 0; I < Kend; I += TM)
      {
        int Iend = (I + TM < Kend) ? (I + TM) : Kend;

        for (k = K; k < Kend; ++k)
        {
          /* i must satisfy I <= i < min(Iend, k). */
          int i_start = I;
          int i_stop  = (k < Iend) ? k : Iend; /* exclusive upper bound */

          if (i_start >= i_stop)
            continue;

          /* Pointer to the source row B[k][J..Jend-1] (read-only here). */
          DATA_TYPE *restrict b_k = &B[k][J];

          for (i = i_start; i < i_stop; ++i)
          {
            DATA_TYPE a_ki = A[k][i];
            /* Pointer to the destination row B[i][J..Jend-1]. */
            DATA_TYPE *restrict b_i = &B[i][J];

            /* Innermost loop over contiguous columns in B.
               Both b_i and b_k refer to row-major slices, so this
               loop is unit-stride and a good target for SIMD/FMA. */
            int width = Jend - J;
            for (j = 0; j < width; ++j)
            {
              b_i[j] += a_ki * b_k[j];
            }
          }
        }
      }
    }
  }

  /* --------------------------------------------------------------------
   * Step 2: scale B by alpha.
   *
   * This realizes:
   *   B[i][j] = alpha * ( B_in[i][j] +
   *                       sum_{k=i+1..M-1} A[k][i] * B_in[k][j] )
   *
   * The separation from Step 1 guarantees that all uses of B[k][j] in
   * the accumulation phase see the original (unscaled) values. */
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_N; j++)
      B[i][j] *= alpha;

#pragma endscop

}


