  /* ------------------------------------------------------------------
   * Phase 1: accumulate strictly-lower-triangular contributions
   *
   *   B[i, j] <- B[i, j] + sum_{k=i+1..M-1} A[k, i] * B[k, j]
   *
   * We use the following loop structure:
   *
   *   for jj in column tiles:
   *     for k = 1 .. M-1:
   *       for i = 0 .. k-1:
   *         B[i, jj:jj+TJJ) += A[k, i] * B[k, jj:jj+TJJ)
   *
   * Properties:
   *   - Inner-most loop walks along j (columns of B), which is
   *     contiguous in memory (row-major B) and thus vectorization-
   *     friendly.
   *   - For fixed (k, i), A[k][i] is loaded once and reused across the
   *     entire j-panel (SAXPY-style update).
   *   - B[k][*] is read-only in this phase; each B[i][*] is updated
   *     only from rows k > i, as in the original algorithm.
   *
   * Parallelization:
   *   - Each iteration over jj touches a disjoint set of columns of B,
   *     so we can safely parallelize the outer jj-loop with OpenMP.
   *   - There are no cross-column dependencies.
   *
   * If compiled without -fopenmp, the OpenMP pragmas are ignored and
   * the kernel executes sequentially but remains fully correct.
   * ------------------------------------------------------------------ */
#pragma omp parallel for schedule(static) private(i,j,k)
  for (int jj = 0; jj < _PB_N; jj += TJJ)
