           Using a separate index jj2 exposes a clean unit-stride
           inner loop for the compiler to vectorize. 'restrict' here
           tells the compiler that Bi and Bk point to non-overlapping
           memory regions (different rows of B). */
        DATA_TYPE *restrict Bi = &B[i][jj];
        DATA_TYPE *restrict Bk = &B[k][jj];

        for (int jj2 = 0; jj2 < tile_width; ++jj2)
        {
          Bi[jj2] += a_ki * Bk[jj2];
        }
      }
    }
  }

